const express = require('express')
const { requireAuth } = require('./auth')
const app = express()
app.use(express.json())

function requireAdmin(req, res, next) {
  if (req.headers['x-role'] === 'admin') return next()
  res.status(403).end()
}

app.get('/admin/users', requireAdmin, (req, res) => res.json([{ id: 1, email: 'a@example.com' }]))

app.use(requireAuth)

app.delete('/admin/users/:id', requireAdmin, (req, res) => res.status(204).end())
app.get('/me', (req, res) => res.json(req.user))

app.listen(3000)

